head.script:
scwin.onpageload = function () {
};

scwin.onpageunload = function () {

};

scwin.checkVal = function() {
	const attr_readonly = WebSquare.wUnit.getDomById('wq_uuid_1___input').parentNode.getAttribute('readonly')				
	const attr_disabled = WebSquare.wUnit.getDomById('wq_uuid_1___input').parentNode.getAttribute('disabled')
	return attr_readonly === null && attr_disabled === null;
}
scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
	WebSquare.wUnit.addCommand('pause', '500');
	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}
scwin.unitTest();
